import {decodeCountries,PIAZZA} from './geography.js';
import {WeatherService,labels,milanTime} from './weather.js';
import {EventScheduler} from './events.js';
import {news,agenda} from './data.js';
import {LocalTransport} from './transport.js';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const weather=new WeatherService(),scheduler=new EventScheduler(),transport=new LocalTransport();let engine=null,selectedCity='milano',panel='news',view='map',manual='auto',messages=[];let mapScale=1,mapX=0,mapY=0,mapDragging=null,mapMoved=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3500);}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();engine&&(engine.keys={});}
$('.modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
function info(){modal(`<div class="eyebrow">ITALIA BEL PAESE SIMULATOR · V0.1</div><h2>Un piccolo pezzo d’Italia.<br>Un mondo da costruire.</h2><p>Questa è una demo navigabile, in terza persona, di Piazza Duomo. Se WebGL non è disponibile si attiva un rendering CPU, con grafica 3D più semplificata. L’ambiente usa modelli procedurali originali: orientamento e disposizione sono indicativi, le geometrie sono provvisorie e non costituiscono una ricostruzione fedele.</p><ul><li><strong>Grafica:</strong> Three.js, modelli originali, pavimentazione procedurale e oggetti ripetuti ottimizzati.</li><li><strong>Meteo:</strong> dati modellistici Open-Meteo se disponibili. In caso di errore compare «Simulazione». I comandi atmosfera sono prove visive.</li><li><strong>Giornale:</strong> selezione verificata il 29 ottobre 2026, senza aggiornamento automatico.</li><li><strong>Eventi:</strong> nessun concerto reale in piazza caricato. La prova evento è solo locale.</li><li><strong>Chat:</strong> messaggi locali di questa sessione. Multiplayer ed economia non sono attivi.</li></ul><p>Riferimenti: <a href="${PIAZZA.sources[0].url}" target="_blank" rel="noopener">Lombardia Beni Culturali</a> · <a href="${PIAZZA.sources[1].url}" target="_blank" rel="noopener">Italia.it</a>. Mappa: <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener">Natural Earth, pubblico dominio</a>. Three.js: licenza MIT.</p>`);}
$('#nav-about').onclick=info;$('#info-button').onclick=info;
function tick(){const date=new Date();$('#clock').textContent=milanTime(date);$('#local-date').textContent=new Intl.DateTimeFormat('it-IT',{timeZone:'Europe/Rome',weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(date);if(engine){$('#scene').dataset.playerX=engine.player.position.x.toFixed(2);$('#scene').dataset.playerZ=engine.player.position.z.toFixed(2);$('#scene').dataset.renderer=engine.softwareFallback?'cpu':'webgl';$('#scene').dataset.triangles=String(engine.renderer.info.render.triangles);}const st=scheduler.state();engine?.setEvent(st);$('#event-banner').hidden=view!=='game'||st.phase==='idle';if(st.phase!=='idle')$('#event-banner').textContent=(st.demo?'EVENTO DIMOSTRATIVO · ':'EVENTO VERIFICATO · ')+(st.phase==='preparing'?'Preparativi in corso. Spettacolo tra pochi secondi.':'Spettacolo attivo · palco, luci e folla.');if(panel==='events'){const status=$('#demo-status');if(status)status.textContent=st.phase==='idle'?'Demo inattiva':st.phase==='preparing'?'Preparativi · spettacolo dopo 12 secondi':'Spettacolo demo in corso';}}
setInterval(tick,1000);tick();
function weatherSummary(){const d=weather.data;$('#temperature').textContent=Math.round(d.temperature)+'°';$('#weather-summary-label').textContent=labels[d.mode];$('#weather-icon').textContent={sun:'☀',cloud:'☁',rain:'☂',fog:'≋'}[d.mode]||'☀';$('#weather-badge').textContent=d.simulated?'SIMULAZIONE':'OPEN-METEO';engine?.setWeather(manual,d);if(panel==='weather')renderPanel();}
async function refreshWeather(){const b=$('#refresh-weather');if(b){b.disabled=true;b.textContent='Aggiornamento…';}await weather.refresh();weatherSummary();}
refreshWeather();setInterval(refreshWeather,15*60*1000);
$$('[data-panel]').forEach(b=>b.onclick=()=>{panel=b.dataset.panel;$$('[data-panel]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b));});renderPanel();});
function renderPanel(){const d=weather.data;const el=$('#side-content');if(panel==='news'){el.innerHTML=`<div class="panel-title"><h3>Giornale di Milano</h3><span>EDIZIONE LOCALE</span></div><p class="source-notice">Notizie reali · selezione verificata il 29/10/2026.<br>Archivio editoriale, non un feed in diretta.</p>${news.map(n=>`<article class="news-item"><div class="news-meta"><span>${n.category}</span><time>${n.date}</time></div><h4>${n.title}</h4><p>${n.summary}</p><a class="source-link" href="${n.url}" target="_blank" rel="noopener">${n.source} · fonte <span>↗</span></a></article>`).join('')}<div class="game-news"><span>DAL MONDO DI ITALIA BEL PAESE SIMULATOR</span><p>Milano è la prima tappa. Piazza Duomo ti aspetta: scegli il pin sulla mappa per iniziare.</p></div>`;}
 if(panel==='weather'){el.innerHTML=`<div class="panel-title"><h3>Bollettino meteo</h3><span>${d.simulated?'SIMULAZIONE':'DATI ESTERNI'}</span></div><p class="source-notice">${d.simulated?'Dati meteo non disponibili. Valori dimostrativi: non descrivono il tempo reale.':'Fonte: Open-Meteo · condizioni da modello meteo, non osservazioni di una stazione in piazza.'}</p><div class="weather-details"><div><label>Temperatura</label><strong>${d.temperature} °C</strong></div><div><label>Condizioni</label><strong>${labels[d.mode]}</strong></div><div><label>Vento a 10 m</label><strong>${d.wind} km/h</strong></div><div><label>Visibilità ${!d.simulated?'(oraria)':''}</label><strong>${d.visibility==null?'N/D':(d.visibility/1000).toFixed(1)+' km'}</strong></div></div><p class="source-notice">${d.updatedAt?'Dati: '+esc(d.updatedAt.replace('T',' '))+' · Europe/Rome':'Aggiornamento reale: non disponibile.'}<br>Aggiornamento automatico ogni 15 minuti.</p><a class="source-link" href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo · attribuzione CC BY 4.0 <span>↗</span></a><button class="panel-button" id="refresh-weather">Aggiorna meteo</button><p class="empty-note">In piazza puoi provare sole, nuvole, pioggia, nebbia e notte. Un’atmosfera selezionata manualmente è sempre una simulazione visiva.</p>`;$('#refresh-weather').onclick=refreshWeather;}
 if(panel==='events'){el.innerHTML=`<div class="panel-title"><h3>Agenda Milano</h3><span>APPUNTAMENTI REALI</span></div><p class="source-notice">Annunci verificati il 29/10/2026. Controlla il programma ufficiale prima di organizzare una visita.</p>${agenda.map(e=>`<article class="event-item"><strong>${e.title}</strong><p>${e.date}<br>${e.time}<br>⌖ ${e.place}</p><a class="source-link" href="${e.url}" target="_blank" rel="noopener">${e.source} <span>↗</span></a></article>`).join('')}<p class="empty-note">Nessun evento con data, ora e fonte verificati in Piazza Duomo è caricato nel prototipo. Gli appuntamenti in altre sedi non attivano eventi in piazza.</p><div class="game-news"><span>LABORATORIO · SOLO GIOCO</span><p>Prova la sequenza: preparativi → spettacolo → fine. È un evento inventato per il test, non un concerto reale.</p><button class="panel-button" id="start-demo">Prova evento in piazza →</button><button class="panel-button" id="stop-demo">Ferma demo</button><p id="demo-status">Demo inattiva</p></div>`;$('#start-demo').onclick=async()=>{if(view!=='game')await enterGame();if(engine){scheduler.startDemo();tick();toast('Demo locale: preparativi avviati.');}};$('#stop-demo').onclick=()=>{scheduler.stopDemo();tick();toast('Evento dimostrativo terminato.');};}
 if(panel==='chat'){el.innerHTML=`<div class="panel-title"><h3>Chat Milano</h3><span>DEMO LOCALE</span></div><p class="source-notice">Solo tu, in questa sessione. Non ci sono altri giocatori collegati né utenti simulati.</p><div class="chat-label">CANALE / MILANO · LOCALE</div><div class="chat-log" id="chat-log">${messages.length?'':'<p class="empty-note">La tua prima parola alla città.<br>Scrivi un messaggio per provare l’interfaccia.</p>'}</div><form class="chat-form"><input id="chat-input" aria-label="Messaggio chat locale" placeholder="Scrivi a Milano…" maxlength="300" required autocomplete="off"><button aria-label="Invia messaggio locale">→</button></form><p class="micro">Messaggi non inviati in rete. Si cancellano al ricaricamento.</p>`;for(const m of messages)appendMessage(m);$('.chat-form').onsubmit=e=>{e.preventDefault();const input=$('#chat-input'),text=input.value.trim();if(!text)return;transport.send({text,time:milanTime()});input.value='';};}}
function appendMessage(m){const log=$('#chat-log');if(!log)return;log.querySelector('.empty-note')?.remove();const node=document.createElement('div');node.className='chat-message';const label=document.createElement('small');label.textContent='TU · LOCALE · '+m.time;node.append(label,document.createTextNode(m.text));log.append(node);log.scrollTop=log.scrollHeight;}
transport.addEventListener('message',e=>{messages.push(e.detail);if(messages.length>100)messages.shift();if(panel==='chat')appendMessage(e.detail);});renderPanel();
// Geographic overview. All coastlines are decoded from bundled Natural Earth data.
async function initMap(){try{const response=await fetch('assets/world.json');if(!response.ok)throw Error('Map load');const countries=decodeCountries(await response.json());const svg=$('#map-svg'),layer=$('#geo-layer');let W=1000,H=780;svg.setAttribute('viewBox',`0 0 ${W} ${H}`);const project=([lon,lat])=>[550+(lon-12.5)*47,390-(lat-42)*63];const ns='http://www.w3.org/2000/svg';const add=(name,attrs,parent=layer)=>{let n=document.createElementNS(ns,name);for(let [k,v]of Object.entries(attrs))n.setAttribute(k,v);parent.append(n);return n;};
 for(let c of countries){const polys=c.polygons.filter(p=>p[0].some(([lon,lat])=>lon>-10&&lon<35&&lat>28&&lat<54));if(!polys.length)continue;let path=polys.map(p=>p.map(r=>'M'+r.map(pt=>project(pt).map(v=>v.toFixed(1)).join(',')).join('L')+'Z').join('')).join('');const italy=c.id==='380';add('path',{d:path,fill:italy?'#93ac89':'#446c61',stroke:italy?'#c1d2a4':'#6a8e7c','stroke-width':italy?1.3:.7,'fill-rule':'evenodd',filter:italy?'url(#land-shadow)':'none'});if(italy)add('path',{d:path,fill:'url(#terrain)','pointer-events':'none'});}
 const text=(str,lon,lat,cls,extra={})=>{let p=project([lon,lat]);let node=add('text',{x:p[0],y:p[1],class:cls,...extra});node.textContent=str;return node;};
 [['FRANCIA',3.2,44.2],['SVIZZERA',8.2,47.3],['AUSTRIA',13.8,48.3],['SLOVENIA',16.3,46.5],['CROAZIA',18.1,44.7]].forEach(v=>text(...v,'country-label'));text('M A R   T I R R E N O',10.2,39.7,'sea-label');text('M A R   A D R I A T I C O',15.6,42.7,'sea-label',{transform:'rotate(45 '+project([15.6,42.7]).join(' ')+')'});text('M A R   I O N I O',17,37.9,'sea-label');text('SARDEGNA',8.7,40,'country-label',{'font-size':8,fill:'#c3d3af'});text('SICILIA',13.6,37.35,'country-label',{'font-size':8,fill:'#c3d3af'});
 for(let [city,lon,lat] of [['TORINO',7.68,45.07],['VENEZIA',12.32,45.44],['FIRENZE',11.25,43.77],['ROMA',12.5,41.9],['NAPOLI',14.27,40.85],['PALERMO',13.36,38.11],['BARI',16.87,41.12]]){let [x,y]=project([lon,lat]);add('circle',{cx:x,cy:y,r:2.6,fill:'#f0e8c3',opacity:.7});text(city,lon+.16,lat-.02,'map-city',{'font-size':8,opacity:.8});}
 let [x,y]=project([9.19,45.464]);const pin=add('g',{class:'pin',role:'button',tabindex:0,'aria-label':'Milano, seleziona città',transform:`translate(${x} ${y})`});add('circle',{r:31,fill:'#d3ecc0','fill-opacity':'.08',class:'pin-outer'},pin);add('circle',{r:19,fill:'none',stroke:'#cae5b6','stroke-opacity':'.4','stroke-width':1},pin);add('path',{d:'M0 8C-4 2-9-3-9-8A9 9 0 0 1 9-8C9-3 4 2 0 8Z',fill:'#d4eac0',stroke:'#173d33','stroke-width':1.2},pin);add('circle',{cx:0,cy:-8,r:3,fill:'#3d6550'},pin);let label=add('text',{x:24,y:-3,fill:'#e5efd6','font-size':14,'font-weight':600,'letter-spacing':1.5},pin);label.textContent='MILANO';let small=add('text',{x:24,y:12,fill:'#b6d7ab','font-size':7,'letter-spacing':1},pin);small.textContent='ESPLORA LA CITTÀ';
 const select=(city='milano')=>{selectedCity=city;$('#location-card').hidden=false;const title=$('#location-card h2');if(title)title.textContent=city==='palermo'?'Palermo':'Milano';const place=$('#location-card h3');if(place)place.textContent=city==='palermo'?'Centro storico di Palermo':'Piazza Duomo';};pin.addEventListener('click',()=>{if(!mapMoved)select('milano');});pin.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select('milano');}});
 let [px,py]=project([13.3615,38.1157]);const pal=add('g',{class:'pin',role:'button',tabindex:0,'aria-label':'Palermo, seleziona città',transform:`translate(${px} ${py})`});add('circle',{r:15,fill:'#d4eac0','fill-opacity':'.17'},pal);add('circle',{r:8,fill:'#d4eac0',stroke:'#173d33','stroke-width':2},pal);let pl=add('text',{x:17,y:5,fill:'#f1eed9','font-size':12,'font-weight':600},pal);pl.textContent='PALERMO';pal.addEventListener('click',()=>{if(!mapMoved)select('palermo');});pal.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select('palermo');}});
 $('#map-loading').hidden=true;svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.12:1/1.12);},{passive:false});svg.addEventListener('pointerdown',e=>{mapMoved=false;mapDragging={x:e.clientX,y:e.clientY,id:e.pointerId};});svg.addEventListener('pointermove',e=>{if(!mapDragging)return;let dx=e.clientX-mapDragging.x,dy=e.clientY-mapDragging.y;if(Math.abs(dx)+Math.abs(dy)>2)mapMoved=true;if(mapMoved){mapX+=dx*W/svg.getBoundingClientRect().width;mapY+=dy*H/svg.getBoundingClientRect().height;mapDragging={x:e.clientX,y:e.clientY,id:e.pointerId};updateMap();}});addEventListener('pointerup',()=>mapDragging=null);svg.addEventListener('pointercancel',()=>mapDragging=null);
 }catch(e){$('#map-loading').innerHTML='Mappa non disponibile. <button id="map-fallback" class="glass-btn">Seleziona Milano →</button>';$('#map-fallback').onclick=()=>$('#location-card').hidden=false;}}
function updateMap(){$('#geo-layer').setAttribute('transform',`translate(${500+mapX} ${390+mapY}) scale(${mapScale}) translate(-500 -390)`);}
function zoom(f){mapScale=Math.min(4,Math.max(.7,mapScale*f));updateMap();}
$('#zoom-in').onclick=()=>zoom(1.25);$('#zoom-out').onclick=()=>zoom(.8);$('#reset-map').onclick=()=>{mapScale=1;mapX=mapY=0;updateMap();};$('#close-location').onclick=()=>$('#location-card').hidden=true;initMap();
function showHelp(){modal(`<div class="eyebrow">BENVENUTO IN PIAZZA</div><h2>Muoviti. Guardati intorno.<br>Prenditi il tuo tempo.</h2><ul><li><strong>W A S D / frecce</strong> — cammina nella piazza.</li><li><strong>Maiusc</strong> — corri.</li><li><strong>Mouse + trascina</strong> — ruota la visuale in terza persona.</li><li><strong>Rotella</strong> — avvicina o allontana la telecamera.</li><li><strong>E</strong> — interagisci vicino a un ingresso o un monumento.</li><li><strong>Su telefono</strong> — usa le frecce a schermo e trascina per guardarti intorno.</li></ul><p>Prova l’atmosfera con i controlli in alto a destra. Apri «Eventi» per avviare una sequenza dimostrativa con palco e folla.</p><p>Gli edifici sono modelli originali provvisori. I negozi hanno interni dimostrativi testuali; non ci sono acquisti.</p><button class="primary modal-primary" id="play-now">Inizia a esplorare <span>→</span></button>`);$('#play-now').onclick=()=>$('#modal').close();}
let entering=false;
async function enterGame(){if(entering)return;entering=true;$('#enter').disabled=true;$('#enter').textContent='Preparazione della città…';view='game';$('#engine-error').hidden=true;$('#atlas').hidden=true;$('#game').hidden=false;$('#world-status').textContent=(selectedCity==='palermo'?'Palermo / centro storico':'Milano / Piazza Duomo')+' · dati OSM';$('#scene-description').textContent=selectedCity==='palermo'?'Geografia reale OSM · nessuna facciata fotografica certificata':'Scena iniziale illustrativa · geografia OSM esterna';try{if(engine&&engine.city!==selectedCity){engine.pause();engine.dispose?.();engine=null;}if(!engine){const {PiazzaEngine}=await import('./engine.js');engine=new PiazzaEngine($('#scene'),{city:selectedCity,onNear:h=>{$('#interaction').hidden=!h;if(h)$('#interact-button span').textContent=h.title;},onInteract:interact});engine.setWeather(manual,weather.data);if(engine.softwareFallback){$('#scene-description').textContent='Modalità CPU · 3D semplificato · geometrie provvisorie';toast('WebGL assente: esplorazione 3D semplificata via CPU.');}}engine.start();if(!sessionStorage.getItem('iv-help')){showHelp();sessionStorage.setItem('iv-help','1');}}catch(e){console.error(e);$('#engine-error').hidden=false;$('#engine-error').innerHTML='<h2>La scena 3D non è disponibile</h2><p>Il prototipo richiede WebGL. Prova un browser aggiornato con accelerazione grafica attiva. Mappa e pannelli restano disponibili.</p><button class="primary" id="error-back">Torna alla mappa →</button>';$('#error-back').onclick=backMap;}finally{entering=false;$('#enter').disabled=false;$('#enter').innerHTML='Esplora la città <span>→</span>';}}
function backMap(){view='map';engine?.pause();$('#game').hidden=true;$('#atlas').hidden=false;$('#world-status').textContent='2 città / geografia sperimentale';}
$('#enter').onclick=enterGame;$('#back-map').onclick=backMap;$('.brand').onclick=e=>{e.preventDefault();backMap();};$('#nav-explore').onclick=backMap;$('#help-button').onclick=showHelp;
$$('[data-weather]').forEach(b=>b.onclick=()=>{manual=b.dataset.weather;$$('[data-weather]').forEach(x=>x.classList.toggle('selected',x===b));$('#atmos-label').textContent=manual==='auto'?'AUTO':'SIMULAZIONE';engine?.setWeather(manual,weather.data);toast(manual==='auto'?'Atmosfera collegata a ora locale e bollettino.':'Atmosfera dimostrativa: '+labels[manual]);});
function interact(h){if(!h)return;if(h.type==='cafe'||h.type==='atelier'){modal(`<div class="eyebrow">INGRESSO INTERATTIVO · DEMO</div><h2>${h.type==='cafe'?'Caffè della Piazza':'Atelier Milano'}</h2><p>${h.type==='cafe'?'Entri per una pausa, tra il profumo del caffè e i rumori della piazza.':'Una piccola vetrina affacciata sulla città. Colori, tessuti e dettagli milanesi.'}</p><p>Questo è un negozio immaginario del gioco. Nella V0.1 l’ingresso apre questa scheda dimostrativa: l’interno 3D e l’economia sono futuri moduli.</p><button class="primary modal-primary" id="shop-exit">Torna in piazza <span>→</span></button>`);$('#shop-exit').onclick=()=>$('#modal').close();return;}const texts={duomo:'Il Duomo chiude il lato est della piazza. Questo modello procedurale evoca facciata, portali e guglie; non rappresenta un rilievo architettonico. L’interno non è incluso nella V0.1.',galleria:'L’ingresso monumentale della Galleria si trova sul lato nord. Il modello include un arco e un passaggio coperto dimostrativi. L’area esplorabile della V0.1 si ferma al margine della piazza.',monumento:'Il monumento equestre a Vittorio Emanuele II è al centro della piazza. La statua e il basamento sono qui reinterpretati con geometrie originali semplificate.'};modal(`<div class="eyebrow">SCOPRI MILANO</div><h2>${h.title}</h2><p>${texts[h.type]}</p><p><a href="${PIAZZA.sources[0].url}" target="_blank" rel="noopener">Fonte geografica: Lombardia Beni Culturali ↗</a></p>`);}
$('#interact-button').onclick=()=>interact(engine?.near);
$$('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(engine){engine.keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId);}});for(let ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>{if(engine)engine.keys[b.dataset.key]=false;});});
$('#scene').addEventListener('webglcontextlost',e=>{e.preventDefault();engine?.pause();toast('Contesto grafico interrotto. Ricarica per riaprire la piazza.');});
// Expose read-only diagnostics for QA and future integration.
window.italiaBelPaeseSimulator={version:'0.1.0',get state(){return {view,panel,weather:{...weather.data},event:scheduler.state(),player:engine?{x:engine.player.position.x,z:engine.player.position.z}:null,graphics:engine?{renderer:engine.softwareFallback?'cpu':'webgl',drawCalls:engine.renderer.info.render.calls,triangles:engine.renderer.info.render.triangles}:null};}};
